from urllib.parse import urlsplit

ALLOWED_HOSTS = {"assets.example"}

class Rejected(ValueError):
    pass

def fetch(url, resolve, connect):
    parsed = urlsplit(url)
    host = parsed.hostname
    if parsed.scheme != "https" or host not in ALLOWED_HOSTS:
        raise Rejected("destination is not allowlisted")
    addresses = tuple(resolve(host))
    if not addresses:
        raise Rejected("host resolved to no addresses")
    if any(address.is_private or address.is_loopback or address.is_link_local for address in addresses):
        raise Rejected("resolved address is not public")
    return connect(addresses, parsed.path)

